    compare: `<div class="compare-card"><div><small>SAME SESSION</small><strong>DEX +</strong><span>direction</span></div><div class="compare-rule-wrap"><div class="compare-rule"></div></div><div><small>SAME SESSION</small><strong>DEI 0.78</strong><span>magnitude</span></div><p class="compare-note" style="grid-column:1/-1;margin:0;color:var(--amber);font:700 14px var(--mono);text-align:center">different lenses · not interchangeable</p></div>`,
    "session-compare": `<div class="compare-card"><div><small>SESSION A · 07/24</small><strong>ASK 220</strong><span>SPX 5900 C · 09:42 ET</span></div><div class="compare-rule-wrap"><div class="compare-rule"></div></div><div><small>SESSION B · 07/25</small><strong>ASK 180</strong><span>SPX 5900 C · 10:03 ET</span></div><p class="compare-note" style="grid-column:1/-1;margin:0;color:var(--amber);font:700 14px var(--mono);text-align:center">same contract · same recipe · new observation</p></div>`,
