    "season-purpose": `<div class="ledger-card"><div class="chart-title">SEASON REVIEW <b>method, not leaderboard</b></div><div class="ledger-row"><b>review</b><span>evidence workflow</span><em>✓</em></div><div class="ledger-row"><b>exclude</b><span>directional hit rate</span><em>—</em></div><div class="ledger-row"><b>show</b><span>reproducibility + gaps</span><em>→</em></div><div class="ledger-row"><b>boundary</b><span>no universal claim</span><em>✓</em></div></div>`,
    "season-coverage": `<div class="ledger-card"><div class="chart-title">SEASON COVERAGE <b>sample boundary</b></div><div class="ledger-row"><b>surface</b><span>TradingFlow workbench</span><em>✓</em></div><div class="ledger-row"><b>objects</b><span>symbols · contracts · sessions</span><em>✓</em></div><div class="ledger-row"><b>method</b><span>cohort · report · blind replay</span><em>✓</em></div><div class="ledger-row"><b>review</b><span>retrospective · cadence</span><em>✓</em></div></div>`,
    "season-learning": `<div class="ledger-card"><div class="chart-title">DURABLE LEARNINGS <b>carry forward</b></div><div class="ledger-row"><b>recipe</b><span>fixed before result</span><em>✓</em></div><div class="ledger-row"><b>scope</b><span>visible beside claims</span><em>✓</em></div><div class="ledger-row"><b>report</b><span>challengeable by design</span><em>✓</em></div><div class="ledger-row"><b>repair</b><span>versioned, not rewritten</span><em>→</em></div></div>`,
    "season-gaps": `<div class="invalid-card"><span>UNRESOLVED INVENTORY</span><strong>Missing fields, limited samples, stale context, and unresolved reads stay visible.</strong><small>A clean review names its gaps instead of filling them with confidence.</small></div>`,
    "season-evidence": `<div class="compare-card"><div><small>EVIDENCE</small><strong>REPRODUCIBLE</strong><span>same packet · same rules</span></div><div class="compare-rule-wrap"><div class="compare-rule"></div></div><div><small>INFERENCE</small><strong>OPEN</strong><span>no forecast advantage claimed</span></div><p class="compare-note" style="grid-column:1/-1;margin:0;color:var(--amber);font:700 14px var(--mono);text-align:center">better process evidence ≠ directional prediction</p></div>`,
    "season-boundary": `<div class="ledger-card"><div class="chart-title">WHAT THIS REVIEW CANNOT SAY <b>boundary</b></div><div class="ledger-row"><b>intent</b><span>not observable from print</span><em>—</em></div><div class="ledger-row"><b>direction</b><span>not asserted</span><em>—</em></div><div class="ledger-row"><b>probability</b><span>small sample ≠ odds</span><em>—</em></div><div class="ledger-row"><b>universal performance</b><span>not established</span><em>—</em></div></div>`,
    "season-next": `<div class="ledger-card"><div class="chart-title">NEXT SEASON HANDOFF <b>start clean</b></div><div class="ledger-row"><b>carry</b><span>review packet + cadence</span><em>✓</em></div><div class="ledger-row"><b>close</b><span>Season 1 rules stay historical</span><em>✓</em></div><div class="ledger-row"><b>open</b><span>new hypothesis · S2E01</span><em>→</em></div><div class="ledger-row"><b>test</b><span>state the new boundary</span><em>?</em></div></div>`,
    dte: `<div class="dte-card"><div><small>${symbol} · CONTRACT A</small><strong>2 DTE</strong><span>near event · illustrative</span></div><div><small>${symbol} · CONTRACT B</small><strong>60 DTE</strong><span>farther event · illustrative</span></div></div>`,
    iv: `<div class="iv-card"><small>${symbol} · IMPLIED VOLATILITY · ILLUSTRATIVE</small><div class="iv-line"><i style="height:32%"></i><i style="height:48%"></i><i style="height:56%"></i><i style="height:72%"></i><i style="height:66%"></i><i style="height:82%"></i></div><div class="iv-axis"><span>near</span><span>term structure</span><span>far</span></div><p>Compare volatility by expiry and moneyness.</p></div>`,
    moneyness: `<div class="moneyness-card"><div class="spot">${symbol} SPOT</div><div class="strike below">470 P</div><div class="strike at">480 ATM</div><div class="strike above">490 C</div><div class="moneyness-line"></div></div>`,
    structure: `<div class="structure-card"><div class="structure-pill">OI <b>${symbol} · reported</b></div><div class="structure-pill">ΔOI <b>${symbol} · snapshot change</b></div><div class="structure-pill">GEX <b>${symbol} · model context</b></div><div class="structure-pill">WALLS <b>${symbol} · map levels</b></div></div>`,
    outro: `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY</small><strong>Discover · Inspect · Validate · Compare · Decide</strong><p>${esc(episodes.find((episode) => episode.scenes.some((scene) => scene[3] === kind))?.next ?? "the next research workflow")}</p></div></div>`,
    "outro-loop": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>Discover · Inspect · Validate · Compare · Invalidate · Replay · Decide</strong><p>S1E09 · The Single-Stock Event Workflow</p></div></div>`,
    "outro-season": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 1</small><strong>${symbol} · event note</strong><p>Illustrative: compare 2 DTE vs 60 DTE, map moneyness, then write the invalidation. Next: S1E10 · false-positive autopsy.</p></div></div>`,
    "outro-autopsy": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>${symbol} · false-positive autopsy</strong><p>Keep the observation. Lower the claim when the alternative survives. Next: S1E11 · build a repeatable scanner.</p></div></div>`,
    "outro-scanner": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>${symbol} · repeatable scanner</strong><p>Same universe, same filters, new timestamp. Next: S1E12 · turn candidates into a hypothesis log.</p></div></div>`,
    "outro-hypothesis": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>SPX 5900 C · hypothesis log</strong><p>Keep the observation, test the alternatives, and record the invalidation. Next: S1E13 · replay across sessions.</p></div></div>`,
    "outro-replay": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>SPX 5900 C · replay across sessions</strong><p>Same rules, two sessions, one honest update. Next: S1E14 · build a cohort of replays.</p></div></div>`,
    "outro-cohort": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>SPX · replay cohort</strong><p>Keep every row, version every recipe, and describe the sample. Next: S1E15 · write a replay report another analyst can challenge.</p></div></div>`,
    "outro-report": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>SPX · challengeable replay report</strong><p>Show the scope, rows, contradictions, and resolution. Next: S1E16 · audit the method with a blind replay.</p></div></div>`,
    "outro-blind": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>SPX · blind replay audit</strong><p>Observe first, reveal later, and version the disagreement. Next: S1E17 · compare analyst reads without forcing agreement.</p></div></div>`,
    "outro-analyst": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · NEXT</small><strong>SPX · analyst read comparison</strong><p>Share the packet, trace the divergence, and log nuance. Next: S1E18 · calibrate the read without collapsing it.</p></div></div>`,
