    "s2e10-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 2 · S2E10</small><strong>Cadence set · process health visible</strong><p>Next: S2E11 · publish a Season 2 review without turning process evidence into a scorecard.</p></div></div>`,
    "season2-next": `<div class="ledger-card"><div class="chart-title">NEXT SEASON HANDOFF <b>start clean</b></div><div class="ledger-row"><b>carry</b><span>review packet + cadence</span><em>✓</em></div><div class="ledger-row"><b>close</b><span>Season 2 stays historical</span><em>✓</em></div><div class="ledger-row"><b>open</b><span>new hypothesis · S3E01</span><em>→</em></div><div class="ledger-row"><b>test</b><span>state the new boundary</span><em>?</em></div></div>`,
    "s2e11-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 2 COMPLETE</small><strong>Method review · clean handoff</strong><p>Carry the packet, cadence, and boundaries forward. Next: S3E01 · start a new season with a new hypothesis.</p></div></div>`,
