    "s3e03-shared": `<div class="ledger-card"><div class="chart-title">SHARED FACTS <b>align before inference</b></div><div class="ledger-row"><b>contract</b><span>SPX 5900 C · same</span><em>✓</em></div><div class="ledger-row"><b>source / time</b><span>Option Trades · 09:42 ET</span><em>✓</em></div><div class="ledger-row"><b>sequence</b><span>print → quote → next check</span><em>✓</em></div><div class="ledger-row"><b>interpretation</b><span>still analyst-layer</span><em>?</em></div></div>`,
    "s3e03-divergence": `<div class="invalid-card"><span>FIRST DIVERGENCE · DIAGNOSTIC</span><strong>Mark the earliest field where the reads split.</strong><small>Selection · scope · missingness · method · interpretation. Start at the first branch, not the final disagreement.</small></div>`,
    "s3e03-resolution": `<div class="compare-card"><div><small>NOTE A</small><strong>KEEP</strong><span>historical read intact</span></div><div class="compare-rule-wrap"><div class="compare-rule"></div></div><div><small>NOTE B</small><strong>KEEP</strong><span>historical read intact</span></div><p class="compare-note" style="grid-column:1/-1;margin:0;color:var(--amber);font:700 14px var(--mono);text-align:center">resolution · unresolved · repair question carried forward</p></div>`,
    "s3e03-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 3 · S3E03</small><strong>Disagreement mapped · history intact</strong><p>Next: S3E04 · repair the first divergence without rewriting either analyst's read.</p></div></div>`,
    "s3e04-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 3 · S3E04</small><strong>Smallest repair · history intact</strong><p>Next: S3E05 · run the repaired packet across a cohort and measure what actually changed.</p></div></div>`,
    "s3e05-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 3 · S3E05</small><strong>Repaired cohort · lineage visible</strong><p>Next: S3E06 · publish the cohort report with repair lineage before the next blind replay.</p></div></div>`,
    "s3e06-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 3 · S3E06</small><strong>Report published · challenge surface open</strong><p>Next: S3E07 · run a blind replay before the next update and keep the prior resolution hidden.</p></div></div>`,
    "s3e07-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 3 · S3E07</small><strong>Blind replay locked · prior result revealed later</strong><p>Next: S3E08 · compare the blind replay with the published cohort and keep both resolutions visible.</p></div></div>`,
    "s3e08-outro": `<div class="outro-card"><div class="outro-mark">TF</div><div><small>TRADINGFLOW ACADEMY · SEASON 3 · S3E08</small><strong>Comparison logged · uncertainty preserved</strong><p>Next: S3E09 · calibrate vocabulary after the comparison while preserving uncertainty.</p></div></div>`,
