    "s3e10-review": `<div class="ledger-card"><div class="chart-title">SEASON 3 REVIEW <b>question + boundary</b></div><div class="ledger-row"><b>question</b><span>does the packet locate drift?</span><em>✓</em></div><div class="ledger-row"><b>scope</b><span>SPX · packet · cohort · replay</span><em>✓</em></div><div class="ledger-row"><b>show</b><span>process evidence + gaps</span><em>→</em></div><div class="ledger-row"><b>cannot say</b><span>intent · direction · odds</span><em>—</em></div></div>`,
    "s3e10-gaps": `<div class="invalid-card"><span>UNRESOLVED INVENTORY · PUBLISH IT</span><strong>Missing fields, limited rows, stale context, and unresolved reads stay visible.</strong><small>A review packet names its gaps instead of filling them with confidence.</small></div>`,
    "s3e10-handoff": `<div class="ledger-card"><div class="chart-title">NEXT VERSION HANDOFF <b>history stays intact</b></div><div class="ledger-row"><b>published</b><span>v2 · cohort + blind replay</span><em>✓</em></div><div class="ledger-row"><b>repair question</b><span>missing freshness field</span><em>→</em></div><div class="ledger-row"><b>next rows</b><span>future cohort only</span><em>→</em></div><div class="ledger-row"><b>boundary</b><span>no rewritten history</span><em>✓</em></div></div>`,
