    "s4e03-fields": `<div class="drawer-card"><div class="drawer-title">SPX RANK ROW <b>fields behind attention</b></div><div class="drawer-tabs"><span class="active">SCOPE</span><span>FRESHNESS</span><span>FLOW LENS</span></div><div class="drawer-fields"><b>Universe</b><span>canonical · declared</span><b>Session</b><span>selected · as-of visible</span><b>Coverage</b><span>required fields present</span></div></div>`,
    "s4e03-candidate": `<div class="rank-card"><div class="rank-row active"><b>01</b><span>SPX</span><em>candidate · selected</em><strong>open drawer</strong></div><div class="rank-row"><b>02</b><span>QQQ</span><em>candidate</em><strong>hold</strong></div><div class="rank-row"><b>03</b><span>MSFT</span><em>candidate</em><strong>hold</strong></div><p class="compare-note" style="margin:20px 0 4px;color:var(--amber);font:700 14px var(--mono);text-align:center">candidate → inspect → validate</p></div>`,
    "s4e03-counter": `<div class="invalid-card"><span>COUNTER-EVIDENCE · TEST THE RANK</span><strong>Missing rows, stale context, denominator drift, or a different lens can invert relative attention.</strong><small>Keep the rank row; lower its usefulness when the comparison boundary changes.</small></div>`,
    "s4e03-no-signal": `<div class="scope-card"><div class="chart-title">RANK BOUNDARY <b>descriptive only</b></div><div class="scope-row"><b>direction</b><span>not asserted</span><em>blocked</em></div><div class="scope-row"><b>intent</b><span>not inferred</span><em>blocked</em></div><div class="scope-row"><b>probability</b><span>not computed</span><em>blocked</em></div><div class="scope-row"><b>decision</b><span>requires inspection</span><em>next</em></div></div>`,
    "s4e03-log": `<div class="ledger-card"><div class="chart-title">RANK HANDOFF <b>replayable inspection</b></div><div class="ledger-row"><b>view</b><span>Rank Symbols · selected session</span><em>✓</em></div><div class="ledger-row"><b>row</b><span>SPX · candidate · selected</span><em>✓</em></div><div class="ledger-row"><b>scope</b><span>universe · as-of · lens</span><em>✓</em></div><div class="ledger-row"><b>next</b><span>symbol drawer · freshness check</span><em>→</em></div></div>`,
