    "s4e04-stop": `<div class="invalid-card"><span>FRESHNESS STOP · DO NOT FILL GAPS</span><strong>Stale or missing context lowers the usefulness of this drawer.</strong><small>Keep the row visible, record the gap, and request the next valid snapshot instead of inferring intent.</small></div>`,
    "s4e04-read": `<div class="ledger-card"><div class="chart-title">DRAWER READ <b>observation ≠ intent</b></div><div class="ledger-row"><b>observed</b><span>ASK 220 · 09:42:16 ET</span><em>✓</em></div><div class="ledger-row"><b>known scope</b><span>SPX 5900 C · 45 DTE</span><em>✓</em></div><div class="ledger-row"><b>unknown</b><span>paired leg / follow-through</span><em>?</em></div><div class="ledger-row"><b>next check</b><span>fresh snapshot · same lens</span><em>→</em></div></div>`,
