    "s4e06-quote": `<div class="compare-card"><div><small>QUOTE</small><strong>NBBO</strong><span>bid · mid · ask</span></div><div class="compare-rule-wrap"><div class="compare-rule"></div></div><div><small>SEQUENCE</small><strong>NEXT</strong><span>neighboring print + snapshot</span></div><p class="compare-note" style="grid-column:1/-1;margin:0;color:var(--amber);font:700 14px var(--mono);text-align:center">attach the next check before writing the claim</p></div>`,
